SELECT * FROM (SELECT CASE WHEN monthly_fee >= 264 THEN 'high' WHEN monthly_fee >= 88 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, ROUND((100 * SUM(CASE WHEN plan = 'premium' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_premium FROM subscriptions WHERE monthly_fee < 160 GROUP BY CASE WHEN monthly_fee >= 264 THEN 'high' WHEN monthly_fee >= 88 THEN 'mid' ELSE 'low' END) AS x WHERE pct_premium < 60 ORDER BY pct_premium, monthly_fee_bucket DESC;
